        DO $$
        BEGIN
            IF to_regclass('public.export_template') IS NULL THEN
                RETURN;
            END IF;

            WITH ranked AS (
                SELECT export_template_id,
                       version,
                       row_number() OVER (PARTITION BY fk_institution_id, lower(name), version ORDER BY export_template_id) AS rn
                FROM export_template
            )
            UPDATE export_template t
            SET version = left(r.version, 40) || '-' || r.rn,
                definition = jsonb_set(t.definition, '{version}', to_jsonb(left(r.version, 40) || '-' || r.rn))
            FROM ranked r
            WHERE t.export_template_id = r.export_template_id AND r.rn > 1;

            IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uk_export_template_institution_name_version') THEN
                ALTER TABLE export_template
                    ADD CONSTRAINT uk_export_template_institution_name_version UNIQUE (fk_institution_id, name, version);
            END IF;
        END $$;



Sert à avertir si des doublons existent déjà dans la BD
-->



        DO $$
        DECLARE
            spec text[];
            specs text[][] := ARRAY[
                ARRAY['recording_unit', 'full_identifier', 'uk_recording_unit_project_identifier'],
                ARRAY['specimen', 'full_identifier', 'uk_specimen_project_identifier'],
                ARRAY['container', 'identifier', 'uk_container_project_identifier'],
                ARRAY['phase', 'identifier', 'uk_phase_project_identifier']];
            duplicates text;
        BEGIN
            FOREACH spec SLICE 1 IN ARRAY specs
            LOOP
                CONTINUE WHEN to_regclass('public.' || spec[1]) IS NULL;
                CONTINUE WHEN EXISTS (SELECT 1 FROM pg_constraint WHERE conname = spec[3])
                           OR to_regclass('public.' || spec[3]) IS NOT NULL;

                EXECUTE format(
                    'SELECT string_agg(format(''(projet %%s, %%L ×%%s)'', fk_action_unit_id, %2$I, n), '', '')
                     FROM (SELECT fk_action_unit_id, %2$I, count(*) AS n FROM %1$I
                           WHERE fk_action_unit_id IS NOT NULL AND %2$I IS NOT NULL
                           GROUP BY fk_action_unit_id, %2$I HAVING count(*) > 1) d',
                    spec[1], spec[2])
                INTO duplicates;

                IF duplicates IS NULL THEN
                    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I UNIQUE (fk_action_unit_id, %I)',
                                   spec[1], spec[3], spec[2]);
                ELSE
                    RAISE WARNING 'Identifiants en double dans %, contrainte % non posée, à réparer à la main : %',
                        spec[1], spec[3], duplicates;
                END IF;
            END LOOP;
        END $$;
